import { useCallback, useEffect, useSyncExternalStore } from 'react'
import {
    diagramEditSessionService,
    type DiagramPersistentTool,
    type DiagramTransientGesture,
} from '../../services/diagrams/diagram_edit_session_service'

export interface DiagramActiveToolStore {
    getActiveToolSnapshot: () => DiagramPersistentTool
    subscribeActiveTool: (listener: () => void) => () => void
}

export interface DiagramTransientGestureStore {
    getTransientGestureSnapshot: () => DiagramTransientGesture | null
    subscribeTransientGesture: (listener: () => void) => () => void
}

export interface DiagramInteractionCancellation {
    cancelActiveInteraction: () => boolean
}

/** Subscribes one leaf to active persistent diagram tool. */
export function useActiveDiagramTool(service: DiagramActiveToolStore = diagramEditSessionService) {
    return useSyncExternalStore(
        service.subscribeActiveTool,
        service.getActiveToolSnapshot,
        service.getActiveToolSnapshot,
    )
}

/** Subscribes one leaf to temporary placement, edge, or move gesture state. */
export function useDiagramTransientGesture(service: DiagramTransientGestureStore = diagramEditSessionService) {
    return useSyncExternalStore(
        service.subscribeTransientGesture,
        service.getTransientGestureSnapshot,
        service.getTransientGestureSnapshot,
    )
}

/** Cancels active diagram interaction from Escape while editor UI is mounted. */
export function useCancelDiagramInteractionOnEscape(
    service: DiagramInteractionCancellation = diagramEditSessionService,
) {
    const handleKeyDown = useCallback((event: KeyboardEvent) => {
        if (event.defaultPrevented || event.key !== 'Escape') return
        if (service.cancelActiveInteraction()) event.preventDefault()
    }, [service])

    useEffect(() => {
        window.addEventListener('keydown', handleKeyDown)

        return () => window.removeEventListener('keydown', handleKeyDown)
    }, [handleKeyDown])
}

import { Box, Typography } from '@mui/material'
import { useRef, type MouseEvent, type PointerEvent, type ReactNode } from 'react'
import {
    diagramEditSessionService, type DiagramEditSessionService,
} from '../../services/diagrams/diagram_edit_session_service'
import { diagramGeometryService, type DiagramGeometryService } from '../../services/diagrams/diagram_geometry_service'
import {
    diagramSelectionService, type DiagramSelectionService,
} from '../../services/diagrams/diagram_selection_service'
import {
    EditableDiagramActivations,
    EditableDiagramEdges,
    EditableDiagramFragments,
    EditableDiagramGroups,
    EditableDiagramLifelines,
    EditableDiagramNodes,
} from './editable_diagram_collections'
import { convertClientToDiagramCoordinates } from './diagram_coordinate_conversion'
import { DiagramSelectionRectangle } from './diagram_selection_rectangle'
import { DiagramResizeHandles } from './diagram_resize_handles'
import { DiagramObjectDetailsDialog } from './diagram_object_details_dialog'
import {
    diagramObjectDetailsService, type DiagramObjectDetailsService,
} from './diagram_object_details_service'
import { DIAGRAM_EDITOR_ROOT_ATTRIBUTE, useDeleteDiagramSelectionOnDeleteKey } from './use_diagram_delete_key'
import { useDiagramSurfaceField } from './use_diagram_geometry'
import { useEditableDiagramMetadataField } from './use_editable_diagram'

interface EditableDiagramProps {
    details?: DiagramObjectDetailsService
    geometry?: DiagramGeometryService
    selection?: DiagramSelectionService
    session?: DiagramEditSessionService
}

interface MetadataLeafProps {
    session?: DiagramEditSessionService
}

/** Title of the New diagram; it observes that one metadata field. */
export function EditableDiagramTitle({ session = diagramEditSessionService }: MetadataLeafProps) {
    return <Typography variant="h6">{useEditableDiagramMetadataField('title', session) ?? ''}</Typography>
}

/** Description of the New diagram; it observes that one metadata field. */
export function EditableDiagramDescription({ session = diagramEditSessionService }: MetadataLeafProps) {
    return (
        <Typography color="text.secondary" variant="body2">
            {useEditableDiagramMetadataField('description', session) ?? ''}
        </Typography>
    )
}

/**
 * Sizes the New drawing surface. Its children arrive as an element through `children`, so a surface bound change
 * resizes the box without rerendering the collection hosts inside it.
 */
export function EditableDiagramSurface({
    children,
    geometry = diagramGeometryService,
    selection = diagramSelectionService,
    session = diagramEditSessionService,
}: {
    children: ReactNode,
    geometry?: DiagramGeometryService,
    selection?: DiagramSelectionService,
    session?: DiagramEditSessionService,
}) {
    const height = useDiagramSurfaceField('height', geometry)
    const width = useDiagramSurfaceField('width', geometry)
    const activePointerIdRef = useRef<number | null>(null)
    const suppressNextClickRef = useRef(false)
    const diagramPointFromPointer = (event: PointerEvent<HTMLDivElement>) => {
        const bounds = event.currentTarget.getBoundingClientRect()
        const viewportMetrics = { bounds: { left: bounds.left, top: bounds.top }, scrollLeft: 0, scrollTop: 0 }

        return convertClientToDiagramCoordinates(event, viewportMetrics, session.getViewportScaleSnapshot()).diagramPoint
    }
    const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
        if (event.button !== 0 || session.getActiveToolSnapshot() !== 'select') return
        if ((event.target as Element).closest('[data-diagram-id], [data-diagram-resize-handle]')) return

        event.preventDefault()
        activePointerIdRef.current = event.pointerId
        suppressNextClickRef.current = false
        selection.beginRectangleSelection(diagramPointFromPointer(event))
        event.currentTarget.setPointerCapture?.(event.pointerId)
    }
    const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
        if (activePointerIdRef.current !== event.pointerId) return

        selection.updateRectangleSelection(diagramPointFromPointer(event))
    }
    const releasePointer = (event: PointerEvent<HTMLDivElement>) => {
        if (event.currentTarget.hasPointerCapture?.(event.pointerId)) {
            event.currentTarget.releasePointerCapture?.(event.pointerId)
        }
        activePointerIdRef.current = null
    }
    const handlePointerUp = (event: PointerEvent<HTMLDivElement>) => {
        if (activePointerIdRef.current !== event.pointerId) return

        selection.completeRectangleSelection(diagramPointFromPointer(event))
        suppressNextClickRef.current = true
        releasePointer(event)
    }
    const handlePointerCancel = (event: PointerEvent<HTMLDivElement>) => {
        if (activePointerIdRef.current !== event.pointerId) return

        selection.cancelRectangleSelection()
        releasePointer(event)
    }
    const handleClick = (event: MouseEvent<HTMLDivElement>) => {
        if (suppressNextClickRef.current) {
            suppressNextClickRef.current = false

            return
        }
        if (session.getActiveToolSnapshot() !== 'select') return
        if ((event.target as Element).closest('[data-diagram-id], [data-diagram-resize-handle]')) return

        selection.clear()
    }

    return (
        <Box
            aria-label="New diagram"
            onClick={handleClick}
            onPointerCancel={handlePointerCancel}
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
            sx={{ height, position: 'relative', touchAction: 'none', width }}
        >
            {children}
        </Box>
    )
}

/**
 * Root of the New diagram. It composes stable hosts and leaves and subscribes to no diagram state itself, so no
 * edit inside the diagram can rerender it.
 */
export function EditableDiagram({
    details = diagramObjectDetailsService,
    geometry = diagramGeometryService,
    selection = diagramSelectionService,
    session = diagramEditSessionService,
}: EditableDiagramProps) {
    useDeleteDiagramSelectionOnDeleteKey(selection)

    return (
        <Box
            {...{ [DIAGRAM_EDITOR_ROOT_ATTRIBUTE]: 'true' }}
            sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}
        >
            <Box>
                <EditableDiagramTitle session={session} />
                <EditableDiagramDescription session={session} />
            </Box>
            <EditableDiagramSurface geometry={geometry} selection={selection} session={session}>
                <EditableDiagramGroups details={details} geometry={geometry} selection={selection} session={session} />
                <EditableDiagramFragments geometry={geometry} session={session} />
                <EditableDiagramLifelines geometry={geometry} session={session} />
                <EditableDiagramActivations geometry={geometry} session={session} />
                <EditableDiagramEdges details={details} geometry={geometry} selection={selection} session={session} />
                <EditableDiagramNodes details={details} geometry={geometry} selection={selection} session={session} />
                <DiagramResizeHandles geometry={geometry} selection={selection} session={session} />
                <DiagramSelectionRectangle selection={selection} />
            </EditableDiagramSurface>
            <DiagramObjectDetailsDialog details={details} session={session} />
        </Box>
    )
}

import { act, cleanup, render } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'
import type { DiagramData } from '../../services/diagrams/diagram_data'
import { DiagramEditSessionService } from '../../services/diagrams/diagram_edit_session_service'
import type { DiagramRecord } from '../../services/diagrams/diagram_index'
import type { DiagramViewSourceSnapshot } from '../../services/diagrams/diagram_view_service'
import { useActiveDiagramTool, useDiagramTransientGesture } from './use_diagram_tool'

const diagram: DiagramData = {
    edges: [],
    groups: [],
    meta: { description: 'Orders architecture', title: 'Overview', type: 'architecture', version: 1 },
    nodes: [],
}
const record: DiagramRecord = { actionId: 'overview', id: 'diagram-1', label: 'Overview', path: 'diagram.json' }

class DiagramSourceStub extends EventTarget {
    private readonly source: DiagramViewSourceSnapshot = { diagram, record }

    getSourceSnapshot = () => this.source

    subscribeSource = (listener: () => void) => {
        this.addEventListener('sourceChanged', listener)

        return () => this.removeEventListener('sourceChanged', listener)
    }
}

function createService() {
    const service = new DiagramEditSessionService(new DiagramSourceStub())
    service.bindProject({ branch: 'main', id: 'project', rootPath: 'C:/repo' })
    service.start()

    return service
}

function ActiveToolLeaf({ counter, service }: {
    counter: ReturnType<typeof vi.fn<(...values: unknown[]) => void>>
    service: DiagramEditSessionService
}) {
    counter(useActiveDiagramTool(service))

    return null
}

function GestureLeaf({ counter, service }: {
    counter: ReturnType<typeof vi.fn<(...values: unknown[]) => void>>
    service: DiagramEditSessionService
}) {
    counter(useDiagramTransientGesture(service))

    return null
}

afterEach(cleanup)

describe('diagram tool subscriptions', () => {
    it('rerenders only leaf subscribed to changed interaction primitive', () => {
        const service = createService()
        const toolCounter = vi.fn()
        const gestureCounter = vi.fn()
        render(
            <>
                <ActiveToolLeaf counter={toolCounter} service={service} />
                <GestureLeaf counter={gestureCounter} service={service} />
            </>,
        )

        act(() => service.setActiveTool('node:component'))
        expect(toolCounter).toHaveBeenCalledTimes(2)
        expect(toolCounter).toHaveBeenLastCalledWith('node:component')
        expect(gestureCounter).toHaveBeenCalledOnce()

        act(() => service.beginTransientGesture('placement'))
        expect(toolCounter).toHaveBeenCalledTimes(2)
        expect(gestureCounter).toHaveBeenCalledTimes(2)
        expect(gestureCounter).toHaveBeenLastCalledWith('placement')
    })
})

import { Box, Tab, Tabs, Tooltip, Typography } from '@mui/material';
import {
    useCallback, useId, useState, useSyncExternalStore,
    type SyntheticEvent,
} from 'react';
import {
    diagramEditSessionService,
    type DiagramPersistentTool,
    type DiagramToolboxSection,
} from '../../services/diagrams/diagram_edit_session_service';
import { ResizablePopper } from '../resizable_popper';
import { DiagramCutButton } from './diagram_cut_button';
import { DiagramDeleteButton } from './diagram_delete_button';
import { DiagramToolboxToolButton } from './diagram_toolbox_tool_button';
import { DiagramZoomInButton } from './diagram_zoom_in_button';
import { DiagramZoomOutButton } from './diagram_zoom_out_button';
import { useCancelDiagramInteractionOnEscape } from './use_diagram_tool';

const DIAGRAM_TOOLBOX_SIZE_STORAGE_KEY = 'md2.diagramToolboxSize';
const TOOLBOX_SECTIONS: readonly { id: DiagramToolboxSection, label: string }[] = [
    { id: 'edit', label: 'Edit' },
    { id: 'nodes', label: 'Nodes' },
    { id: 'edges', label: 'Edges' },
    { id: 'groups', label: 'Groups' },
    { id: 'others', label: 'Others' },
];
const INITIAL_TOOLBOX_SIZE = { height: 200, width: 360 };
const MINIMUM_TOOLBOX_SIZE = { height: 120, width: 280 };

interface DiagramToolboxProps {
    boundaryElement: HTMLElement | null;
    session?: {
        getActiveToolboxSectionSnapshot: () => DiagramToolboxSection;
        getActiveToolSnapshot: () => DiagramPersistentTool;
        getViewportScaleSnapshot: () => number;
        cancelActiveInteraction: () => boolean;
        setActiveTool: (tool: DiagramPersistentTool) => void;
        setActiveToolboxSection: (section: DiagramToolboxSection) => void;
        subscribeActiveTool: (listener: () => void) => () => void;
        subscribeActiveToolboxSection: (listener: () => void) => () => void;
        subscribeViewportScale: (listener: () => void) => () => void;
        zoomIn: () => boolean;
        zoomOut: () => boolean;
    };
}

/** Floating shell for diagram tools. Tool leaves are added by their focused feature jobs. */
export function DiagramToolbox({
    boundaryElement,
    session = diagramEditSessionService,
}: DiagramToolboxProps) {
    const [anchorElement, setAnchorElement] = useState<HTMLDivElement | null>(null);
    const titleId = useId();
    useCancelDiagramInteractionOnEscape(session);
    const activeSection = useSyncExternalStore(
        session.subscribeActiveToolboxSection,
        session.getActiveToolboxSectionSnapshot,
        session.getActiveToolboxSectionSnapshot,
    );
    const handleSectionChange = useCallback((_event: SyntheticEvent, section: DiagramToolboxSection) => {
        session.setActiveToolboxSection(section);
    }, [session]);

    return (
        <>
            <Box
                aria-hidden="true"
                ref={setAnchorElement}
                sx={{ height: 0, position: 'absolute', right: 2, top: 5, width: 0 }}
            />
            <ResizablePopper
                anchorElement={anchorElement}
                boundaryElement={boundaryElement}
                closeOnEscape={false}
                focusOnMount={false}
                initialSize={INITIAL_TOOLBOX_SIZE}
                labelId={titleId}
                minimumSize={MINIMUM_TOOLBOX_SIZE}
                open={!!anchorElement && !!boundaryElement}
                paperSx={{
                    bgcolor: 'background.paper',
                    border: 1,
                    borderColor: 'divider',
                    borderRadius: 1.75,
                    boxShadow: 8,
                    flexDirection: 'column',
                }}
                placement="bottom-end"
                resizeFromAllSides
                resizeLabel="Resize diagram toolbox"
                storageKey={DIAGRAM_TOOLBOX_SIZE_STORAGE_KEY}
            >
                <Typography id={titleId} sx={{ px: 1.5, pt: 1.25 }} variant="subtitle2">
                    Diagram tools
                </Typography>
                <Tabs
                    aria-label="Diagram tool sections"
                    onChange={handleSectionChange}
                    scrollButtons="auto"
                    value={activeSection}
                    variant="scrollable"
                >
                    {TOOLBOX_SECTIONS.map(({ id, label }) => (
                        <Tab
                            aria-controls={`${titleId}-${id}-panel`}
                            id={`${titleId}-${id}-tab`}
                            key={id}
                            label={<Tooltip title={label}><Box component="span">{label}</Box></Tooltip>}
                            value={id}
                        />
                    ))}
                </Tabs>
                <Box
                    aria-labelledby={`${titleId}-${activeSection}-tab`}
                    id={`${titleId}-${activeSection}-panel`}
                    role="tabpanel"
                    sx={{ alignContent: 'flex-start', display: 'flex', flex: 1, flexWrap: 'wrap', gap: 1, overflow: 'auto', p: 1.5 }}
                >
                    {activeSection === 'edit' && (
                        <>
                            <DiagramToolboxToolButton
                                label="Select"
                                session={session}
                                tool="select"
                                tooltip="Select diagram objects"
                            />
                            <DiagramZoomInButton session={session} />
                            <DiagramZoomOutButton session={session} />
                            <DiagramCutButton />
                            <DiagramDeleteButton />
                        </>
                    )}
                </Box>
            </ResizablePopper>
        </>
    );
}

